import {esc,avatar,button as btn,eventCard} from './views.js';
import {visibleEvents,user} from './domain.js';
import {EVENT_TYPES} from './data.js';
import {CITIES,CREDIT_PACKS,EVENT_CREDIT_COST} from './demo.js';
import {businesses,rating,balance,euro,insights} from './marketplace.js';
export const citySelect=(value,id='region',name='')=>`<label class="region-select">Regio<select ${name?`name="${name}"`:`id="${id}"`}>${name?'':'<option value="">Alle steden</option>'}${CITIES.map(c=>`<option ${value===c?'selected':''}>${c}</option>`).join('')}</select></label>`;
const stars=n=>`<span class="review-stars" aria-label="${Number(n.toFixed(1))} van 5 sterren">${'★'.repeat(Math.round(n))}${'☆'.repeat(5-Math.round(n))}</span>`;
const ratingLabel=r=>r.count?`${stars(r.average)} <strong>${r.average.toFixed(1)}</strong> <span class="muted">(${r.count})</span>`:'<span class="muted">Nog geen reviews · ontdek als eerste</span>';
const symbols={'':'✦',Koffie:'☕',Muziek:'♫',Sport:'↗',Quiz:'?',Cultuur:'◈',Gaming:'✚',Eten:'◒',Buiten:'☀'};
export function exploreMarketplace(c){const {state,u,eventFilter,savedOnly,region,exploreMode,businessSort}=c;
 const places=exploreMode==='places',list=places?businesses(state,region,eventFilter,businessSort):visibleEvents(state,eventFilter,savedOnly?u.id:'',region);
 return `<div class="page-heading"><span class="eyebrow">JOUW STAD. JOUW MENSEN.</span><h1>Ga samen <em>op pad.</em></h1><p>Nieuwe plannen en plekken met een klik.</p></div><div class="market-tabs" role="group" aria-label="Ontdek activiteiten of bedrijven">${[['events','Activiteiten'],['places','Bedrijven']].map(([id,t])=>`<button data-action="explore-mode" data-id="${id}" aria-pressed="${exploreMode===id}" class="${exploreMode===id?'active':''}">${t}</button>`).join('')}</div><section class="filter-studio" aria-label="Explore filters"><div class="filter-top">${citySelect(region)}${places?`<label>Sorteer<select id="business-sort"><option value="rating" ${businessSort==='rating'?'selected':''}>Aanbevolen</option><option value="reviews" ${businessSort==='reviews'?'selected':''}>Meeste reviews</option><option value="name" ${businessSort==='name'?'selected':''}>Naam A–Z</option></select></label>`:`<button class="saved-toggle ${savedOnly?'active':''}" data-action="saved-toggle" aria-pressed="${savedOnly}">♡ Bewaard</button>`}</div><p class="small muted">Waar heb je zin in?</p><div class="interest-pills" role="group" aria-label="Interesse of soort activiteit">${['',...EVENT_TYPES].map(t=>`<button data-action="event-filter" data-id="${t}" aria-pressed="${eventFilter===t}" class="${eventFilter===t?'active':''}"><span aria-hidden="true">${symbols[t]}</span>${t||'Alles'}</button>`).join('')}</div>${region||eventFilter||(!places&&savedOnly)?btn('Filters wissen','clear-event-filter','','text-button'):''}</section><div class="results-caption"><strong>${list.length} ${places?'plekken':'activiteiten'}</strong><span>${esc(region||'Alle steden')}</span></div>${places?'<p class="small muted">Aanbevolen op basis van sterren én aantal reviews. Reviews in deze demo zijn fictief.</p>':''}<div class="event-grid">${list.map(x=>places?`<article class="place-card"><div class="place-art" style="--place:${esc(x.color||'#6b7863')}"><span>${esc(x.city)}</span><b>${esc(x.name.split(' ').map(w=>w[0]).slice(0,2).join(''))}</b><i>✦</i></div><div class="event-body"><span class="eyebrow">${esc(x.category)}</span><h2>${esc(x.name)}</h2><p>${ratingLabel(rating(state,x.id))}</p><p class="place-description">${esc(x.description)}</p>${btn('Ontdek deze plek ↗','business-detail',x.id,'primary')}</div></article>`:eventCard(state,u,x)).join('')||`<div class="empty"><h2>Even verder kijken?</h2><p>Deze combinatie heeft nog geen resultaten.</p>${btn('Toon alles','clear-event-filter','','primary')}</div>`}</div>`;
}
export function reviewCard(state,u,r,{reply=false}={}){return `<article class="review-card"><div class="review-author">${avatar(user(state,r.student)||{name:'Student'})}<div><strong>${esc(user(state,r.student)?.name||'Student')}</strong><small>${new Date(r.at).toLocaleDateString('nl-BE')} · ${r.demo?'Voorbeeldreview':'Testreview'}</small></div></div>${stars(r.rating)}<p>${esc(r.text)}</p>${r.reply?`<div class="owner-reply"><strong>Antwoord van het bedrijf</strong><p>${esc(r.reply)}</p></div>`:''}${reply?btn(r.reply?'Antwoord aanpassen':'Beantwoord review','reply-review',r.id,'quiet'):r.student!==u.id?btn(`Nuttig (${r.helpful?.length||0})${r.helpful?.includes(u.id)?' ✓':''}`,'helpful-review',r.id,'text-button'):''}</article>`;}
export function businessDetail(state,u,id){const b=user(state,id),r=rating(state,id),mine=r.rows.find(x=>x.student===u.id),events=visibleEvents(state).filter(e=>e.owner===id);return `<span class="eyebrow">${esc(b.city)} · ${esc(b.category)}</span><h2>${esc(b.name)}</h2><p>${ratingLabel(r)}</p><p>${esc(b.description)}</p><p class="small muted">${esc(b.address)}</p><h3>Op de agenda</h3><div class="share-list">${events.map(e=>btn(`${esc(e.title)}<small>${esc(e.date)} · ${esc(e.price)}</small>`,'event-detail',e.id,'share-activity')).join('')||'<p>Nog geen activiteiten.</p>'}</div><section class="review-editor"><h3>${mine?'Jouw review aanpassen':'Hoe was jouw bezoek?'}</h3><p class="small muted">Dit zijn demoreviews, geen echte beoordelingen.</p><form id="review-form" data-business="${id}"><fieldset class="star-picker"><legend>Jouw sterren</legend>${[1,2,3,4,5].map(n=>`<label><input type="radio" name="rating" value="${n}" ${mine?.rating===n?'checked':''} required><span aria-hidden="true">${n} ★</span><span class="sr-only">${n} ${n===1?'ster':'sterren'}</span></label>`).join('')}</fieldset><label>Jouw ervaring<textarea name="text" minlength="3" maxlength="800" required placeholder="Wat maakt deze plek bijzonder?">${esc(mine?.text||'')}</textarea></label><button class="primary">Review opslaan</button></form></section><h3>${r.count} reviews</h3>${[...r.rows].sort((a,b)=>b.at.localeCompare(a.at)).map(x=>reviewCard(state,u,x)).join('')}${btn('Sluiten','close','','quiet')}`;}
const heading=(k,t,p='')=>`<div class="heading"><span class="eyebrow">${k}</span><h1>${esc(t)}</h1><p class="muted">${p}</p></div>`;
export function businessWorkspace(c){const {state,u,page,dashDays,dashEvent,dashOwn}=c,credits=balance(state,u.id),events=state.events.filter(e=>e.owner===u.id);
 const top=`<div class="business-summary"><span>✦ ${esc(u.city)} · ${u.verified?'Zichtbaar in Explore':'Wacht op verificatie'}</span>${btn(`${credits} credits →`,'nav','credits','credit-pill')}</div>`;
 if(page==='credits')return `${top}${heading('RUIMTE VOOR NIEUWE CONNECTIES','Jouw credits.','10 credits per eerste publicatie. Concepten en latere bewerkingen zijn gratis.')}<div class="wallet-banner"><div><span>Beschikbaar saldo</span><strong>${credits}<small> credits</small></strong></div><p>Goed voor ${Math.floor(credits/EVENT_CREDIT_COST)} nieuwe evenementen.<br>Geen echte betaling. Geen abonnement.</p></div><div class="credit-packs">${CREDIT_PACKS.map((p,i)=>`<article class="panel ${i===1?'featured-pack':''}"><span class="eyebrow">${i===1?'MEER SAMEN DOEN':p.caption}</span><h2>${p.name}</h2><strong class="pack-number">${p.credits}<small> credits</small></strong><p>${p.caption}</p><p class="pack-price">${euro(p.cents)} <small>demoprijs</small></p>${btn('Pakket kiezen','buy-pack',p.id,'primary')}</article>`).join('')}</div><h2>Je creditgeschiedenis</h2><p class="small muted">Verwijderen van een evenement geeft geen credits terug.</p><div class="panel table-wrap"><table><thead><tr><th>Moment</th><th>Omschrijving</th><th>Credits</th><th>Demo betaald</th></tr></thead><tbody>${state.creditLedger.filter(t=>t.business===u.id).slice().reverse().map(t=>`<tr><td>${new Date(t.at).toLocaleDateString('nl-BE')}</td><td>${esc(t.label)}</td><td><strong>${t.amount>0?'+':''}${t.amount}</strong></td><td>${t.cents?euro(t.cents):'—'}</td></tr>`).join('')}</tbody></table></div>`;
 if(page==='business-profile')return `${top}${heading('JOUW PLEK IN DE STAD',u.name)}<form id="business-form" class="panel form-panel"><label>Bedrijfsnaam<input name="name" value="${esc(u.name)}" required maxlength="100"></label>${citySelect(u.city,'','city')}<label>Categorie<select name="category">${[...new Set([u.category,...EVENT_TYPES])].map(x=>`<option ${x===u.category?'selected':''}>${esc(x)}</option>`).join('')}</select></label><label>Beschrijving<textarea name="description" required maxlength="500">${esc(u.description)}</textarea></label><label>Locatie<input name="address" value="${esc(u.address)}" required maxlength="150"></label><button class="primary">Bedrijfsprofiel opslaan</button></form><h2>Reviews van studenten</h2><p>${ratingLabel(rating(state,u.id))}</p>${rating(state,u.id).rows.map(r=>reviewCard(state,u,r,{reply:true})).join('')||'<p>Nog geen reviews.</p>'}`;
 if(page==='events')return `${top}${heading('MAAK ER IETS MOOIS VAN','Jouw evenementen.','Publiceren kost 10 credits. Bewerken blijft gratis.')}<p>${btn('＋ Nieuw evenement','new-event','','primary')}</p>${!u.verified?'<p class="notice">Je bedrijf wacht op verificatie. Je kunt alvast gratis concepten maken.</p>':''}<div class="business-events">${events.filter(e=>!e.archived).map(e=>{const i=insights(state,u.id,{event:e.id,days:90,own:dashOwn});return `<article class="panel"><span class="eyebrow">${e.published?'GEPUBLICEERD':'CONCEPT'} · ${esc(e.city)}</span><h2>${esc(e.title)}</h2><p>${esc(e.date)} · ${esc(e.time)} · ${esc(e.price)}</p><div class="event-metrics"><span><b>${i.views}</b> views</span><span><b>${i.bookings}</b> inschrijvingen</span><span><b>${euro(i.revenue)}</b> demo-omzet</span></div><p class="small muted">Laatste 90 dagen · ${dashOwn?'eigen testacties':'inclusief voorbeelddata'}</p><div class="button-row">${btn('Bewerken','edit-event',e.id,'quiet')}${btn('Inzichten ↗','event-insights',e.id,'quiet')}${btn('Verwijderen','delete-event',e.id,'text-button')}</div></article>`;}).join('')}</div>`;
 const opts={days:dashDays,event:dashEvent,own:dashOwn},i=insights(state,u.id,opts),r=rating(state,u.id);
 const metrics=[['Bekeken pagina’s',i.views,'Bedrijfs- en evenementdetails'],['Unieke bezoekers',i.unique,'Studenten die details openden'],['Inschrijvingen',i.bookings,'Actieve demo-inschrijvingen'],['Demo-omzet',euro(i.revenue),'Ticketprijs × inschrijvingen']];
 const bars=Array.from({length:7},(_,n)=>{const date=new Date();date.setHours(0,0,0,0);date.setDate(date.getDate()-6+n);const start=date.getTime(),end=new Date(date.getFullYear(),date.getMonth(),date.getDate()+1).getTime();return {label:new Date(start).toLocaleDateString('nl-BE',{weekday:'short'}),value:i.activity.filter(x=>x.type.endsWith('view')&&Date.parse(x.at)>start&&Date.parse(x.at)<=end).length};}),max=Math.max(1,...bars.map(b=>b.value));
 const regions=CITIES.map(city=>({city,count:i.studentIds.filter(id=>user(state,id)?.city===city).length}));
 const performance=events.map(e=>({e,...insights(state,u.id,{...opts,event:e.id})})).filter(x=>!dashEvent||x.e.id===dashEvent).sort((a,b)=>b.revenue-a.revenue||b.views-a.views);
 return `${top}${heading('JOUW CAMPUS IN BEWEGING','Hallo, '+u.name+'.','Van een eerste blik naar samen iets beleven.')}<section class="dashboard-filters"><label>Periode<select id="dash-days">${[7,30,90].map(n=>`<option value="${n}" ${dashDays===n?'selected':''}>Laatste ${n} dagen</option>`).join('')}</select></label><label>Evenement<select id="dash-event"><option value="">Alle evenementen + bedrijfsprofiel</option>${events.map(e=>`<option value="${e.id}" ${dashEvent===e.id?'selected':''}>${esc(e.title)}${e.archived?' (verwijderd)':''}</option>`).join('')}</select></label><label class="toggle-label"><input type="checkbox" id="dash-own" ${dashOwn?'checked':''}> Alleen eigen testacties</label></section><p class="small muted">${dashOwn?'Live lokale testacties; fictieve voorbeelden zijn uitgesloten.':'Inclusief gesimuleerde voorbeelddata. Schakel hierboven naar je eigen testacties.'} Er worden geen betalingen verwerkt.</p><div class="dashboard-metrics">${metrics.map(([label,value,help])=>`<article class="panel"><span>${label}</span><strong>${value}</strong><small>${help}</small></article>`).join('')}</div><div class="dashboard-columns"><section class="panel"><div class="section-heading"><h2>De afgelopen week</h2><span class="chip">Paginaweergaven</span></div><div class="traffic-chart" role="img" aria-label="Paginaweergaven per dag: ${bars.map(b=>b.label+' '+b.value).join(', ')}">${bars.map(b=>`<div><strong>${b.value}</strong><span style="height:${Math.max(3,b.value/max*130)}px"></span><small>${b.label}</small></div>`).join('')}</div></section><section class="panel"><span class="eyebrow">VAN KIJKEN NAAR MEEDOEN</span><h2>${i.conversion}% schrijft zich in</h2><p class="small muted">Unieke bezoekers met een actieve inschrijving binnen de gekozen periode.</p><div class="engagement-row"><span><b>${i.saves}</b> bewaaracties</span><span><b>${i.shares}</b> gedeeld</span></div><p>${ratingLabel(r)} <small>alle reviews, ongeacht periode</small></p></section></div><div class="dashboard-columns"><section class="panel"><h2>Waar komen je studenten vandaan?</h2>${regions.map(x=>`<div class="region-bar"><span>${x.city}</span><meter min="0" max="${Math.max(1,i.students)}" value="${x.count}">${x.count}</meter><b>${x.count}</b></div>`).join('')}<p class="small muted">${i.students} unieke studenten met een view, bewaaractie, deelactie of inschrijving.</p></section><section class="panel insight-note"><span class="eyebrow">EEN KLEINE VOLGENDE STAP</span><h2>${i.views===0?'Tijd voor een eerste bezoek.':i.bookings===0?'Maak je uitnodiging concreet.':'Bouw voort op die klik.'}</h2><p>${i.views===0?'Wissel naar een student en open je bedrijf of activiteit in Explore. Je ziet het resultaat hier terug.':i.bookings===0?'Een duidelijke titel, tijd en prijs maken de stap naar inschrijven kleiner.':`Je populairste evenement op basis van demo-omzet en views is “${esc(performance[0]?.e.title||'nog niet bekend')}”. Probeer een nieuw concept en vergelijk het resultaat.`}</p>${btn('Nieuw evenement maken','new-event','','quiet')}</section></div><h2>Per evenement</h2><p class="small muted">Actieve inschrijvingen en bruto demo-ticketomzet. Geannuleerde inschrijvingen tellen niet mee. Credits zijn apart en worden niet als omzet geteld.</p><div class="panel table-wrap"><table><thead><tr><th>Evenement</th><th>Views</th><th>Studenten</th><th>Bewaard</th><th>Gedeeld</th><th>Ingeschreven</th><th>Demo-omzet</th></tr></thead><tbody>${performance.map(x=>`<tr><td>${btn(esc(x.e.title),'event-insights',x.e.id,'text-button')}<small>${esc(x.e.city)} · ${x.e.archived?'Verwijderd · historie':x.e.published?'Live':'Concept'}</small></td><td>${x.views}</td><td>${x.unique}</td><td>${x.saves}</td><td>${x.shares}</td><td>${x.bookings}</td><td>${euro(x.revenue)}</td></tr>`).join('')||'<tr><td colspan="7">Maak je eerste evenement om inzichten te verzamelen.</td></tr>'}</tbody></table></div>`;
}
